/**
 * RoutePathOverlay — renders the computed route path on top of the floor plan image.
 *
 * View-based polyline (no new SVG dependency). For each adjacent pair of
 * nodes on the active floor, renders endpoint dots and a connecting line
 * rotated to match the bearing.
 */

import { StyleSheet, View } from 'react-native';
import { ViewportDimensions } from '../../map/mapTransform';

/* ─── Types ─── */

export interface RoutePathPoint {
  x: number;       // normalized [0,1]
  y: number;       // normalized [0,1]
  floorId: number;
}

interface Props {
  path: RoutePathPoint[];
  activeFloorId: number;
  viewport: ViewportDimensions;
  scale: number;
}

/* ─── Helpers (pure, no closure state) ─── */

function segmentBearingDeg(
  from: RoutePathPoint,
  to: RoutePathPoint,
  vp: ViewportDimensions,
  sc: number,
): number {
  const dx = (to.x - from.x) * vp.width * sc;
  const dy = (to.y - from.y) * vp.height * sc;
  return Math.atan2(dy, dx) * (180 / Math.PI);
}

function segmentLen(
  from: RoutePathPoint,
  to: RoutePathPoint,
  vp: ViewportDimensions,
  sc: number,
): number {
  const dx = (to.x - from.x) * vp.width * sc;
  const dy = (to.y - from.y) * vp.height * sc;
  return Math.hypot(dx, dy);
}

/* ─── Coordinate to pixel position ─── */

function toPixel(node: RoutePathPoint, vp: ViewportDimensions, sc: number) {
  return {
    left: node.x * vp.width * sc - 4,
    top:  node.y * vp.height * sc - 4,
  };
}

/* ─── Component ─── */

export function RoutePathOverlay({ path, activeFloorId, viewport, scale }: Props) {
  const floorNodes = path.filter(n => n.floorId === activeFloorId);

  if (floorNodes.length === 0) return null;

  // Single node → draw one dot
  if (floorNodes.length === 1) {
    const { left, top } = toPixel(floorNodes[0], viewport, scale);
    return <View style={[styles.dot, styles.dotStart, { left, top }]} />;
  }

  // Multiple nodes → draw start/end dots + connecting segments
  return (
    <View style={styles.overlay} pointerEvents="none">
      {/* Start dot */}
      <View style={[styles.dot, styles.dotStart, toPixel(floorNodes[0], viewport, scale)]} />

      {/* Segments between consecutive nodes */}
      {floorNodes.slice(1).map((toNode, i) => {
        const fromNode = floorNodes[i];
        const { left: startLeft, top: startTop } = toPixel(fromNode, viewport, scale);
        const { left: endLeft, top: endTop } = toPixel(toNode, viewport, scale);
        const len = segmentLen(fromNode, toNode, viewport, scale);
        const angleDeg = segmentBearingDeg(fromNode, toNode, viewport, scale);

        return (
          <View key={`seg-${i}`} style={styles.overlay} pointerEvents="none">
            {/* Connecting line (anchored at start, rotated) */}
            {len > 0 && (
              <View
                style={[
                  styles.line,
                  { width: len, left: startLeft + 4, top: startTop + 3, transform: [{ rotate: `${angleDeg}deg` }] },
                ]}
              />
            )}
          </View>
        );
      })}

      {/* End dot */}
      <View style={[styles.dot, styles.dotEnd, toPixel(floorNodes[floorNodes.length - 1], viewport, scale)]} />
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  overlay: {
    ...StyleSheet.absoluteFillObject,
  },
  dot: {
    position: 'absolute',
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: '#38bdf8',
  },
  dotStart: {
    backgroundColor: '#4ade80',
  },
  dotEnd: {
    backgroundColor: '#f87171',
  },
  line: {
    position: 'absolute',
    height: 2,
    backgroundColor: '#38bdf8',
    transformOrigin: 'left center',
  },
});

// Route layer — direction cards, summary strip, and guidance start button

export { DirectionStepCard } from './DirectionStepCard';
export type { DirectionStepCardProps } from './DirectionStepCard';

export { RouteSummaryStrip } from './RouteSummaryStrip';
export type { RouteSummaryStripProps } from './RouteSummaryStrip';

export { StartGuidanceButton } from './StartGuidanceButton';
export type { StartGuidanceButtonProps } from './StartGuidanceButton';

/**
 * Tests for ConfidenceIndicator component.
 * Written as .test.tsx but uses React.createElement to avoid Vite 7's
 * TSX transform issue (oxc can't parse TypeScript `import type` syntax).
 * @testing-library/react-native is used via @testing-library/react-native/build.
 */

import { describe, expect, it, vi } from 'vitest';
import * as React from 'react';
import { render, screen, fireEvent } from '@testing-library/react-native';
import { ConfidenceIndicator } from './ConfidenceIndicator';

// ─── Reanimated mock ──────────────────────────────────────────────────────────
// Vitest resolves `react-native-reanimated` from `__mocks__/react-native-reanimated.ts`

const h = React.createElement;

describe('ConfidenceIndicator', () => {
  it('renders with container testID', () => {
    render(h(ConfidenceIndicator, { confidence: 'high' }));
    expect(screen.getByTestId('confidence-indicator')).toBeTruthy();
  });

  it('has Pressable accessibility role', () => {
    render(h(ConfidenceIndicator, { confidence: 'medium' }));
    const el = screen.getByTestId('confidence-indicator');
    expect(el.props.accessibilityRole).toBe('button');
  });

  it('shows accessibility label with confidence level', () => {
    render(h(ConfidenceIndicator, { confidence: 'low' }));
    const el = screen.getByTestId('confidence-indicator');
    expect(el.props.accessibilityLabel).toBe('GPS confidence: low');
  });

  it('tapping the dot toggles the detail label (tap to show)', () => {
    render(h(ConfidenceIndicator, { confidence: 'high' }));
    // Initially no label
    expect(screen.queryByText('GPS OK')).toBeNull();
    // Tap the dot
    fireEvent.press(screen.getByTestId('confidence-dot'));
    expect(screen.getByText('GPS OK')).toBeTruthy();
  });

  it('tapping again hides the detail label', () => {
    render(h(ConfidenceIndicator, { confidence: 'low' }));
    const el = screen.getByTestId('confidence-dot');
    // Show
    fireEvent.press(el);
    expect(screen.getByText('Weak GPS')).toBeTruthy();
    // Hide
    fireEvent.press(el);
    expect(screen.queryByText('Weak GPS')).toBeNull();
  });

  it('renders correctly for none confidence', () => {
    render(h(ConfidenceIndicator, { confidence: 'none' }));
    expect(screen.getByTestId('confidence-indicator')).toBeTruthy();
    fireEvent.press(screen.getByTestId('confidence-dot'));
    expect(screen.getByText('No GPS')).toBeTruthy();
  });

  // ─── PulseRing tests ───────────────────────────────────────────────────────

  it('renders pulse ring when showPulse defaults to true', () => {
    const { root } = render(h(ConfidenceIndicator, { confidence: 'high' }));
    // The PulseRing renders as an Animated.View; in the jsdom mock it
    // renders as a plain div.  The container (confidence-indicator) should
    // contain the pulse ring child.
    const container = screen.getByTestId('confidence-indicator');
    expect(container.props.children).toBeTruthy();
  });

  it('does not render pulse ring when showPulse is false', () => {
    render(h(ConfidenceIndicator, { confidence: 'high', showPulse: false }));
    // Container has a single child (dotTouchable) — no pulse ring div
    const container = screen.getByTestId('confidence-indicator');
    const children = container.props.children;
    // children is an array [pulseRing, dotTouchable] when showPulse is true,
    // or just dotTouchable when false
    if (Array.isArray(children)) {
      expect(children.length).toBe(1);
    }
  });

  it('pulse ring shows for medium confidence', () => {
    const { root } = render(h(ConfidenceIndicator, { confidence: 'medium' }));
    const container = screen.getByTestId('confidence-indicator');
    expect(container.props.children).toBeTruthy();
  });

  it('pulse ring shows for low confidence', () => {
    render(h(ConfidenceIndicator, { confidence: 'low' }));
    const container = screen.getByTestId('confidence-indicator');
    expect(container.props.children).toBeTruthy();
  });

  it('pulse ring shows for none confidence', () => {
    render(h(ConfidenceIndicator, { confidence: 'none' }));
    const container = screen.getByTestId('confidence-indicator');
    expect(container.props.children).toBeTruthy();
  });
});

/**
 * ConfidenceIndicator — colored dot + optional detail popover + pulse ring.
 *
 * Renders a small (12×12px) filled circle whose color reflects the
 * current GPS/heading confidence level.  Tapping the dot toggles a
 * small inline label showing the level name.
 *
 * A PulseRing sub-component renders an animated ring behind the dot
 * during non-idle guidance phases.  It scales and fades continuously
 * using react-native-reanimated.
 */

import { useEffect, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import Animated, {
  Easing,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withTiming,
} from 'react-native-reanimated';

import { useTheme } from '../../theme';

// Re-export for consumers; defined inline to avoid importing guidanceState.ts
// which uses TypeScript type-as-assertion patterns that vitest's oxc parser
// cannot process during test transform.
export type ConfidenceLevel = 'high' | 'medium' | 'low' | 'none';
export const ConfidenceLevel = undefined as unknown as ConfidenceLevel;

// ─── Color map ────────────────────────────────────────────────────────────────

const LABEL_TEXT: Record<ConfidenceLevel, string> = {
  high: 'GPS OK',
  medium: 'Heading?',
  low: 'Weak GPS',
  none: 'No GPS',
};

const ICON_MAP: Record<ConfidenceLevel, string> = {
  high: '',
  medium: '',
  low: '',
  none: '⚠',
};

// ─── PulseRing ───────────────────────────────────────────────────────────────

interface PulseRingProps {
  color: string;
  show: boolean;
}

function PulseRing({ color, show }: PulseRingProps) {
  const scale = useSharedValue(1.0);
  const opacity = useSharedValue(0.6);

  useEffect(() => {
    if (!show) {
      scale.value = 1.0;
      opacity.value = 0;
      return;
    }
    // Reset to starting values before beginning the loop
    scale.value = 1.0;
    opacity.value = 0.6;
    scale.value = withRepeat(
      withSequence(
        withTiming(1.8, { duration: 1000, easing: Easing.out(Easing.ease) }),
        withTiming(1.0, { duration: 0 }),
      ),
      -1,
      false,
    );
    opacity.value = withRepeat(
      withSequence(
        withTiming(0, { duration: 1000, easing: Easing.out(Easing.ease) }),
        withTiming(0.6, { duration: 0 }),
      ),
      -1,
      false,
    );
  }, [show, scale, opacity]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
    opacity: opacity.value,
  }));

  if (!show) return null;

  return (
    <Animated.View
      style={[
        styles.pulseRing,
        { backgroundColor: color },
        animatedStyle,
      ]}
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
    />
  );
}

// ─── ConfidenceIndicator ──────────────────────────────────────────────────────

interface Props {
  confidence: ConfidenceLevel;
  /** Show the pulsing ring. Defaults to true. */
  showPulse?: boolean;
}

export function ConfidenceIndicator({ confidence, showPulse = true }: Props) {
  const [showLabel, setShowLabel] = useState(false);
  const { colors } = useTheme();

  const colorMap: Record<ConfidenceLevel, string> = {
    high: colors.confidenceHigh,
    medium: colors.confidenceMedium,
    low: colors.confidenceLow,
    none: colors.confidenceNone,
  };

  const labelColorMap: Record<ConfidenceLevel, string> = {
    high: colors.successMuted,
    medium: colors.warningMuted,
    low: colors.orangeMuted,
    none: colors.errorMuted,
  };

  const dotColor = colorMap[confidence];
  const labelColor = labelColorMap[confidence];
  const labelText = LABEL_TEXT[confidence];
  const icon = ICON_MAP[confidence];

  return (
    <View
      style={styles.container}
      accessibilityRole="button"
      accessibilityLabel={`GPS confidence: ${confidence}`}
      testID="confidence-indicator"
    >
      {/* PulseRing renders behind the dot via absolute positioning */}
      <PulseRing color={dotColor} show={showPulse} />

      {/* Tappable dot */}
      <Pressable
        style={styles.dotTouchable}
        onPress={() => setShowLabel(s => !s)}
        testID="confidence-dot"
        accessibilityRole="button"
        accessibilityLabel={`GPS confidence: ${confidence}`}
      >
        <View style={[styles.dot, { backgroundColor: dotColor }]}>
          {icon ? <Text style={styles.icon}>{icon}</Text> : null}
        </View>
      </Pressable>

      {/* Label badge */}
      {showLabel && (
        <View
          style={[
            styles.labelBadge,
            { backgroundColor: dotColor + '33', borderColor: dotColor },
          ]}
        >
          <Text style={[styles.labelText, { color: labelColor }]}>
            {labelText}
          </Text>
        </View>
      )}
    </View>
  );
}

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    width: 36,
    height: 36,
  },
  pulseRing: {
    position: 'absolute',
    width: 12,
    height: 12,
    borderRadius: 9999,
  },
  dotTouchable: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  dot: {
    width: 12,
    height: 12,
    borderRadius: 9999,
    alignItems: 'center',
    justifyContent: 'center',
  },
  icon: {
    fontSize: 7,
    color: '#fff',
    lineHeight: 9,
  },
  labelBadge: {
    position: 'absolute',
    top: 32,
    left: '50%',
    transform: [{ translateX: -30 }],
    width: 60,
    borderWidth: 1,
    borderRadius: 6,
    paddingHorizontal: 6,
    paddingVertical: 3,
    alignItems: 'center',
  },
  labelText: {
    fontSize: 10,
    fontWeight: '600',
  },
});

/**
 * Mock react-native-reanimated for jsdom test environment.
 * Provides the animated component primitives that ConfidenceIndicator uses.
 */
'use strict';
const React = require('react');

function View({ style, children, testID }: {
  style?: unknown; children?: React.ReactNode; testID?: string;
}): React.ReactElement {
  return React.createElement('div', { 'data-testid': testID, style }, children);
}

function AnimatedView(props: {
  style?: unknown; children?: React.ReactNode; testID?: string;
}): React.ReactElement {
  return View(props);
}

function useSharedValue(initialValue: number) {
  return { value: initialValue };
}

function useAnimatedStyle(expand: (v: { value: number }) => unknown) {
  return expand({ value: 0 });
}

function withRepeat(inner: unknown, _countOrConfig?: unknown, _config2?: unknown) {
  return inner;
}

function withSequence(inner1: unknown, inner2: unknown) {
  return inner1;
}

function withTiming(value: number, _config?: unknown, _callback?: unknown) {
  return value;
}

function Easing(_config?: unknown) {
  return 0;
}

module.exports = {
  View: AnimatedView,
  Text: View,
  default: {
    createAnimatedComponent: (Component: unknown) => Component,
  },
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withSequence,
  withTiming,
  Easing,
};

import { defineConfig } from 'vitest/config';
import { resolve } from 'node:path';

export default defineConfig({
  resolve: {
    alias: [
      { find: '@shared', replacement: resolve(__dirname, '../src/shared') },
      { find: '@client', replacement: resolve(__dirname, '../src/client') },
      {
        find: /^react-native$/,
        replacement: resolve(__dirname, '__mocks__/react-native.js'),
      },
      {
        find: /^react-native-reanimated$/,
        replacement: resolve(__dirname, '__mocks__/react-native-reanimated.ts'),
      },
    ],
  },
  // Vite 8 uses oxc for TSX transform by default, which doesn't support TypeScript
  // `export type` syntax in worker processes. Use esbuild for TS instead.
  esbuild: {
    ts: true,
  },
  optimizeDeps: {
    // Force esbuild for TypeScript transpilation in both deps and workers
    ts: 'esbuild',
  },
  test: {
    environment: 'jsdom',
    globals: true,
    include: ['**/*.test.ts', '**/*.test.tsx'],
    exclude: ['**/node_modules/**', '**/.git/**'],
    clearMocks: true,
    restoreMocks: true,
    pool: 'forks',
    // Disable oxc in workers — use esbuild for TypeScript
    coverage: {
      provider: 'v8',
    },
  },
});

/**
 * Theme system for CampusNav.
 * Exports color palettes, spacing scale, typography, and the useTheme hook.
 */

import { useColorScheme } from 'react-native';

import { darkColors, lightColors } from './colors';
import { spacing } from './spacing';
import { typography } from './typography';

export { darkColors, lightColors } from './colors';
export { spacing } from './spacing';
export { typography } from './typography';

export interface Theme {
  colors: typeof darkColors | typeof lightColors;
  spacing: typeof spacing;
  typography: typeof typography;
  isDark: boolean;
}

/**
 * Returns the current theme based on the system color scheme.
 *
 * Usage:
 *   const { colors, spacing, typography, isDark } = useTheme();
 */
export function useTheme(): Theme {
  const colorScheme = useColorScheme();
  const isDark = colorScheme === 'dark';
  return {
    colors: isDark ? darkColors : lightColors,
    spacing,
    typography,
    isDark,
  };
}

